/**
 * Finds which M3 spec token each `labs/gb` component token declaration
 * implements. Shared by the audit (audit-gb.mjs) and the spec test generator
 * (gen-spec-tests.mjs).
 *
 * Token files generated by spec-tokens.mjs (`scripts/m3/bindings/*.mjs` with
 * `generate: true`) are bound exactly, from the token set / state each mixin
 * compiles from. For each `--prop: value` in each `@mixin` of a hand-written
 * `_*-tokens.scss`, the matching token is inferred from the component's token
 * sets and the words of the mixin name (variant / size / state / part), with
 * agreement with gb's value and Jetpack Compose token usage as tie-breakers.
 */

import {readdir, readFile} from 'node:fs/promises';
import {dirname, join} from 'node:path';
import {fileURLToPath, pathToFileURL} from 'node:url';
import {compileBinding, declValue, norm, parseMixins, sameValue, STATES} from './gb-compile.mjs';
import {SpecDb, WEB_CONTEXT} from './spec-db.mjs';
import {elementDir, elementDirs} from '../element-dirs.mjs';

export const GB = 'material-design-expressive/components';
export {elementDir, elementDirs} from '../element-dirs.mjs';

/**
 * Spec token-set prefixes per gb component. This (one line per component) is
 * the only component knowledge; everything else is inferred.
 */
export const COMPONENT_SETS = {
  appbar: ['md.comp.app-bar'],
  badge: ['md.comp.badge'],
  button: ['md.comp.button'],
  buttongroup: ['md.comp.button-group'],
  card: ['md.comp.filled-card', 'md.comp.outlined-card', 'md.comp.elevated-card'],
  carousel: ['md.comp.carousel-item'],
  checkbox: ['md.comp.checkbox'],
  chip: ['md.comp.assist-chip', 'md.comp.filter-chip', 'md.comp.input-chip', 'md.comp.suggestion-chip'],
  datepicker: ['md.comp.date-picker.docked', 'md.comp.date-picker.modal', 'md.comp.date-input.modal'],
  dialog: ['md.comp.dialog', 'md.comp.full-screen-dialog'],
  divider: ['md.comp.divider'],
  fab: ['md.comp.fab', 'md.comp.extended-fab'],
  fabmenu: ['md.comp.fab-menu'],
  iconbutton: ['md.comp.icon-button'],
  list: ['md.comp.list'],
  loadingindicator: ['md.comp.loading-indicator'],
  menu: ['md.comp.menus'],
  navbar: ['md.comp.nav-bar'],
  navdrawer: ['md.comp.navigation-drawer'],
  navrail: ['md.comp.nav-rail'],
  progress: ['md.comp.progress-indicator'],
  radio: ['md.comp.radio-button'],
  search: ['md.comp.search-bar', 'md.comp.search-view'],
  select: ['md.comp.filled-select', 'md.comp.outlined-select', 'md.comp.filled-autocomplete', 'md.comp.outlined-autocomplete'],
  segmentedbutton: ['md.comp.outlined-segmented-button'],
  sheet: ['md.comp.sheet.bottom', 'md.comp.sheet.side'],
  slider: ['md.comp.slider'],
  snackbar: ['md.comp.snackbar'],
  splitbutton: ['md.comp.split-button'],
  switch: ['md.comp.switch'],
  tabs: ['md.comp.primary-navigation-tab', 'md.comp.secondary-navigation-tab'],
  textfield: ['md.comp.filled-text-field', 'md.comp.outlined-text-field'],
  timepicker: ['md.comp.time-picker', 'md.comp.time-input'],
  toolbar: ['md.comp.toolbar'],
  tooltip: ['md.comp.plain-tooltip', 'md.comp.rich-tooltip'],
};

const SIZE = {xsmall: 'xs', small: 'sm', medium: 'md', large: 'lg', xlarge: 'xl'};
const SYNONYM = {hover: 'hovered', focus: 'focused', press: 'pressed', drag: 'dragged'};

/** Words used for the same thing in gb and in the spec. */
const PROP_ALIASES = {
  'shape': ['container-shape'],
  'padding-leading': ['leading-space'],
  'padding-trailing': ['trailing-space'],
  'gap': ['icon-label-space', 'between-space'],
  'height': ['container-height'],
  'width': ['container-width'],
};

/**
 * Loads the spec DB, (optional) Compose usage and the generated bindings
 * (`scripts/m3/bindings/*.mjs` with `generate: true`), and returns an
 * analyzer.
 */
export async function loadBindings(specsDir = '.m3-specs') {
  const db = await SpecDb.load(specsDir);
  const usage = new Map();
  try {
    const json = JSON.parse(await readFile(join(specsDir, 'compose-usage.json'), 'utf8'));
    for (const [token, sites] of Object.entries(json.tokens)) usage.set(token, sites);
  } catch {
    console.warn('No compose-usage.json; run scripts/m3/compose-usage.mjs for better matching.');
  }
  const generated = new Map();
  for (const f of await readdir(BINDINGS)) {
    if (!f.endsWith('.mjs')) continue;
    const binding = (await import(pathToFileURL(join(BINDINGS, f)).href)).default;
    // binding.file is relative to the library folder; GB paths are repo-relative.
    if (binding.generate) generated.set(posix(`material-design-expressive/${binding.file}`), binding);
  }
  const includes = await allIncludes();
  return {db, usage, analyze: (dir) => analyze(db, usage, generated, includes, dir)};
}

const BINDINGS = join(dirname(fileURLToPath(import.meta.url)), 'bindings');

function posix(path) {
  return path.replace(/\\/g, '/');
}

/** Every `@include <namespace>.<mixin>` in the gb component stylesheets. */
async function allIncludes() {
  const found = new Set();
  for (const entry of elementDirs()) {
    for (const f of await readdir(entry.dir)) {
      if (!f.endsWith('.scss')) continue;
      const source = await readFile(join(entry.dir, f), 'utf8');
      for (const m of source.matchAll(/@include\s+([\w-]+)\.([\w-]+)\s*[;(]/g)) {
        found.add(`${m[1]}.${m[2]}`);
      }
    }
  }
  return found;
}

/** The `@use` namespace of a `_<name>.scss` partial. */
export function namespaceOf(file) {
  return file.replace(/^_/, '').replace(/\.scss$/, '');
}

/**
 * Analyzes one gb component: every `_*-tokens.scss` in its directory.
 *
 * Token files generated from a binding (`generate: true`) are bound exactly:
 * the binding states the token set / state each mixin compiles from, so each
 * property maps to the tokens it was compiled from. Hand-written files are
 * bound by inference (`findToken`).
 *
 * @return {Promise<undefined | {
 *   dir: string, files: Array<{path, ns, source}>,
 *   records: Array<{file, ns, mixin, prop, have, status, token?, want?, confident?, edited?}>,
 *   tokens: string[], bound: Set<string>, unwired: string[]}>}
 *   `status` is one of match | drift | derived | unbound. `unwired` lists
 *   `<namespace>.<mixin>` names.
 */
async function analyze(db, usage, generated, includes, dir) {
  const prefixes = COMPONENT_SETS[dir];
  if (!prefixes) return undefined;
  const tokenFiles = (await readdir(elementDir(dir)))
    .filter((f) => /^_.*-tokens\.scss$/.test(f))
    .sort();
  if (!tokenFiles.length) return undefined;
  const sets = candidateTokens(db, prefixes);
  const compounds = compoundWords(sets);
  const records = [];
  const bound = new Set();
  const unwired = [];
  const files = [];

  for (const tokenFile of tokenFiles) {
    const path = join(elementDir(dir), tokenFile);
    const ns = namespaceOf(tokenFile);
    const source = await readFile(path, 'utf8');
    files.push({path, ns, source});
    const mixins = parseMixins(source);
    const binding = generated.get(posix(path));
    const compiled = binding ? compileGenerated(db, binding) : undefined;
    const edits = editedProps(source);
    // One-word mixins name variants (`secondary`, `vibrant`, `item`), and
    // size words (`standard-xs`) name size mixins.
    const sizes = new Set(Object.values(SIZE));
    const leads = new Set([
      ...[...mixins.keys()].filter((m) => !m.includes('-')).map((m) => mixinWords(m, compounds)[0]),
      ...[...mixins.keys()].flatMap((m) => m.split('-')).filter((w) => sizes.has(w)),
    ]);
    const avoid = (mixin) => {
      const own = mixin === 'root' ? [] : mixinWords(mixin, compounds);
      return new Set([...leads].filter((w) => !own.includes(w) && !STATES.includes(w) && w !== 'root'));
    };
    const add = (r) => records.push({file: path, ns, ...r});

    for (const [mixin, decls] of mixins) {
      if (binding && mixin === 'inherit') continue;
      const exact = compiled?.get(mixin);
      const words = mixin === 'root' ? [] : mixinWords(mixin, compounds);
      for (const [prop, have] of Object.entries(decls)) {
        if (prop.startsWith('md-')) continue; // e.g. --md-icon-fill: not a spec token
        // Values derived from another component property are not spec values.
        // (A full corner spelled `calc(var(--height) / 2)` is still bound.)
        if (/var\(\s*--(?!md-)/.test(have) && !FULL_CORNER.test(have)) {
          add({mixin, prop, have, status: 'derived'});
          continue;
        }
        const from = exact?.sources.get(prop);
        if (from?.length) {
          // Exact binding: the property is compiled from these tokens.
          from.forEach((t) => bound.add(t));
          let want = exact.decls[prop];
          let same = sameValue(have, want) || equivalent(have, want);
          // A hand `// EDIT:` may fold an opacity token the compiler does not
          // pair with this color (`disabled.selected.track.color` with
          // `disabled.track.opacity`).
          const opacity = opacityFor(db, from[0]);
          if (!same && opacity) {
            const folded = specValue(db, from[0], prop);
            if (folded && (sameValue(have, folded) || equivalent(have, folded))) {
              [want, same] = [folded, true];
              bound.add(opacity);
            }
          }
          const edited = edits.get(mixin)?.has(prop) ?? false;
          add({
            mixin,
            prop,
            have,
            status: same ? 'match' : 'drift',
            token: from[0],
            want,
            // A hand `// EDIT:` override is deliberate; any other difference
            // means the file is out of date with its generator.
            confident: !edited,
            ...(edited ? {edited} : {}),
          });
          continue;
        }
        if (exact) {
          // Other declarations of a generated mixin are `// EDIT:` values
          // the spec has no token for. Credit one only when it equals a
          // token of the sets the mixin compiles from.
          const scoped = sets.filter((t) => exact.scope.some((s) => t.token.startsWith(s)));
          const probe = new Set();
          const record = infer(db, usage, scoped, [], prop, have, probe);
          if (record.status === 'match') {
            probe.forEach((t) => bound.add(t));
            add({mixin, prop, have, ...record, confident: false});
          } else {
            // A hand-folded `hsl(from <color> h s l / N%)` implements the
            // mixin's `x.opacity` token when that is N%.
            const pct = have.match(/^hsl\(from .+ \/ (\d+(?:\.\d+)?)%\)$/)?.[1];
            const part = prop.replace(/-color$/, '');
            if (pct && part !== prop) {
              for (const s of exact.scope) {
                const t = `${s}${part.replace(/-/g, '.')}.opacity`;
                const opacity = db.resolve(t, WEB_CONTEXT)?.resolved?.opacity;
                if (opacity !== undefined && Math.round(opacity * 100) === Math.round(Number(pct))) bound.add(t);
              }
            }
            add({mixin, prop, have, status: 'unbound'});
          }
          continue;
        }
        add({mixin, prop, have, ...infer(db, usage, sets, words, prop, have, bound, avoid(mixin))});
      }
    }

    // Mixins defined in the token file but never included. The generated
    // `inherit` mixin is optional: components that do not forward host
    // values into a shadow root do not use it.
    for (const m of mixins.keys()) {
      if (m === 'inherit') continue;
      if (!includes.has(`${ns}.${m}`)) unwired.push(`${ns}.${m}`);
    }
  }

  return {
    dir,
    path: files[0].path,
    source: files[0].source,
    files,
    records,
    tokens: [...new Set(sets.map((s) => s.token))],
    bound,
    unwired,
  };
}

/**
 * Compiles a generated binding into `mixin -> {decls, sources, scope}`,
 * `scope` being the token-name prefixes the mixin compiles from.
 */
function compileGenerated(db, binding) {
  const exclude = (binding.exclude ?? []).map((p) => new RegExp(p));
  const out = new Map();
  const blocks = [['root', binding.root], ...(binding.mixins ?? []).map((m) => [m.name, m])];
  for (const [name, specs] of blocks) {
    const {decls, sources} = compileBinding(db, specs, exclude, WEB_CONTEXT);
    const scope = [].concat(specs).map(({set, state}) => `${set}.${state ? `${state}.` : ''}`);
    out.set(name, {decls, sources, scope});
  }
  return out;
}

/** `mixin -> Set<prop>` of the `// EDIT:` declarations in a token file. */
function editedProps(source) {
  const out = new Map();
  for (const m of source.replace(/\r\n/g, '\n').matchAll(/@mixin\s+([\w-]+)\s*\{([^}]*)\}/g)) {
    const props = new Set();
    for (const e of m[2].matchAll(/\/\/ EDIT:[^\n]*\n\s*--([\w-]+)\s*:/g)) props.add(e[1]);
    if (props.size) out.set(m[1], props);
  }
  return out;
}

/** Hyphenated token path segments, e.g. `drag-handle`, `focus-indicator`. */
function compoundWords(tokens) {
  const out = new Set();
  for (const {token} of tokens) {
    for (const s of token.split('.')) if (s.includes('-')) out.add(s);
  }
  return out;
}

/**
 * The words of a mixin name, with gb state spellings mapped to the spec's
 * (`hover` -> `hovered`) unless the word starts a compound spec word
 * (`drag-handle` is not `dragged handle`).
 */
function mixinWords(mixin, compounds) {
  const raw = mixin.split('-');
  return raw.map((w, i) => {
    if (!SYNONYM[w]) return w;
    for (let j = i + 2; j <= raw.length; j++) {
      if (compounds.has(raw.slice(i, j).join('-'))) return w;
    }
    return SYNONYM[w];
  });
}

const TYPESCALE = /^var\(--md-sys-typescale-([\w-]+?)(-axes|-tracking)?\)$/;
const TYPE_PARTS = ['font', 'weight', 'size', 'line-height', 'tracking', 'type'];

/**
 * Infers the spec token of one hand-written declaration, adding the tokens it
 * implements to `bound`.
 */
function infer(db, usage, sets, words, prop, have, bound, avoid) {
  // A composite type style, `--x: var(--md-sys-typescale-<style>)` (+ `-axes`
  // / `-tracking`), implements the `x.font` / `.weight` / `.size` /
  // `.line-height` / `.tracking` / `.type` tokens.
  const style = have.match(TYPESCALE);
  if (style && !/-(font|weight|size|line-height)$/.test(style[1])) {
    const suffix = prop.match(/-(axes|tracking)$/)?.[0] ?? '';
    const base = prop.slice(0, prop.length - suffix.length);
    const fontWant = (token) => specValue(db, token, `${base}-font`)?.replace(/-font\)$/, `${suffix})`);
    const hit = findToken(sets, words, `${base}-font`, usage, {
      avoid,
      agrees: (token) => sameValue(have, fontWant(token) ?? ''),
    });
    if (hit) {
      const root = hit.token.replace(/\.font$/, '');
      const want = fontWant(hit.token);
      const token =
        suffix === '-tracking' && db.tokens.has(`${root}.tracking`) ? `${root}.tracking` : hit.token;
      const same = want === undefined || sameValue(have, want) || equivalent(have, want);
      // A weak binding (through a sibling mixin's word) only counts when it
      // agrees.
      if (!same && hit.extra >= WEAK) return {status: 'unbound'};
      for (const p of TYPE_PARTS) if (db.tokens.has(`${root}.${p}`)) bound.add(`${root}.${p}`);
      return {status: same ? 'match' : 'drift', token, want, confident: hit.confident, ...weak(hit)};
    }
  }

  const hit = findToken(sets, words, prop, usage, {
    avoid,
    agrees: (token) => {
      const want = specValue(db, token, prop);
      return want !== undefined && (sameValue(have, want) || equivalent(have, want));
    },
  });
  if (!hit) return {status: 'unbound'};
  const want = specValue(db, hit.token, prop);
  const same = want === undefined || sameValue(have, want) || equivalent(have, want);
  if (!same && hit.extra >= WEAK) return {status: 'unbound'};
  bound.add(hit.token);
  // A color that folds its sibling `.opacity` token implements that too.
  const opacity = opacityFor(db, hit.token);
  if (same && opacity) bound.add(opacity);
  return {status: same ? 'match' : 'drift', token: hit.token, want, confident: hit.confident, ...weak(hit)};
}

/** Marks a binding made through a sibling mixin's word (not spec-tested). */
function weak(hit) {
  return hit.extra >= WEAK ? {weak: true} : {};
}

/**
 * Every token under the component prefixes, as normalized path words
 * relative to the prefix (sizes abbreviated, legacy state names updated).
 */
function candidateTokens(db, prefixes) {
  const tokens = [];
  for (const set of db.sets.keys()) {
    for (const prefix of prefixes) {
      if (set !== prefix && !set.startsWith(`${prefix}.`)) continue;
      // `md.comp.filled-card` contributes `filled` when several prefixes
      // make up one component.
      const variant =
        prefixes.length > 1 ? prefix.replace(/^md\.comp\./, '').split('-').slice(0, -1) : [];
      for (const token of db.tokensInSet(set)) {
        // Legacy state names are renamed only as whole path segments
        // (`hover.` -> `hovered`, but not `drag-handle`, `focus-indicator`).
        const words = token
          .slice(prefix.length + 1)
          .split('.')
          .flatMap((seg) => (SYNONYM[seg] ? [SYNONYM[seg]] : seg.split('-')))
          .map((w) => SIZE[w] ?? w);
        // A set-level `x.color` (no part) is the container color when the
        // set has no `x.container.color` (e.g. `md.comp.badge.color`).
        const setColor = token === `${set}.color` && !db.tokens.has(`${set}.container.color`);
        tokens.push({token, set, prefix, words: [...variant, ...words], setColor});
      }
    }
  }
  // A base-set token (e.g. md.comp.button.icon.color, the filled defaults)
  // whose suffix a variant set also defines is variant-specific: binding it
  // to a variant-neutral mixin is a guess.
  const variantSuffixes = new Set(
    tokens.filter((t) => t.set !== t.prefix).map((t) => t.token.slice(t.set.length + 1)),
  );
  for (const t of tokens) {
    t.shadowed = t.set === t.prefix && variantSuffixes.has(t.token.slice(t.set.length + 1));
  }
  return tokens;
}

/**
 * Finds the spec token for `--prop` in a mixin named by `words`.
 *
 * The property's words must line up with the end of the token path; the
 * remaining path words are "context". Every mixin word must appear in the
 * context, and any state in the context must be named by the mixin. Among
 * matches, the one with the fewest unexplained context words wins.
 */
function findToken(tokens, words, prop, usage, {avoid = new Set(), agrees} = {}) {
  let best;
  // `--container-color` may implement a set-level `color` token.
  const setColor = /(^|-)container-color$/.test(prop) ? prop.replace(/container-color$/, 'color') : undefined;
  for (const spelling of [prop, ...(PROP_ALIASES[prop] ?? []), ...(setColor ? [setColor] : [])]) {
    const propWords = spelling.split('-');
    const onlySetColor = spelling === setColor;
    for (const {token, words: path, shadowed, setColor: isSetColor} of tokens) {
      if (onlySetColor && !isSetColor) continue;
      const context = align(path, propWords);
      if (!context) continue;
      // Navigation components spell selected / unselected `active` /
      // `inactive`.
      const named = (w) => words.includes(w) || words.includes(ACTIVE[w]);
      if (!words.every((w) => context.includes(w) || context.includes(ACTIVE[w]))) continue;
      if (context.some((w) => STATES.includes(w) && !words.includes(w))) continue;
      const unexplained = context.filter((w) => !named(w) && w !== 'enabled');
      // A word naming a sibling mixin (`secondary`, `vibrant`, `segmented`)
      // belongs to that mixin: such a token is a last resort (`weak`).
      const extra = unexplained.length + WEAK * unexplained.filter((w) => avoid.has(w)).length;
      // Among equally explained tokens, prefer the one gb's value agrees
      // with (e.g. `inactive.` vs `active.label-text.color`), then tokens the
      // reference implementation actually uses, then shorter names.
      const agree = agrees?.(token) ? 1 : 0;
      const used = usage.has(token) ? 1 : 0;
      const key = [-extra, agree, used, -path.length];
      const better = !best || compareKeys(key, best.key) > 0;
      // High confidence: no unexplained words, the property is the literal
      // end of the token name, the mixin is not the neutral `root`, and the
      // token is not a variant-specific default.
      const contiguous = path.slice(-propWords.length).join('-') === propWords.join('-');
      const confident = extra === 0 && contiguous && words.length > 0 && !shadowed;
      if (better) best = {token, extra, key, confident};
    }
  }
  return best;
}

const WEAK = 100;
const ACTIVE = {selected: 'active', unselected: 'inactive', active: 'selected', inactive: 'unselected'};

function compareKeys(a, b) {
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return a[i] - b[i];
  return 0;
}

/**
 * Matches `propWords` as a subsequence of `path` anchored at the last word
 * and returns the unmatched path words, or undefined.
 */
function align(path, propWords) {
  if (path[path.length - 1] !== propWords[propWords.length - 1]) return undefined;
  const context = [];
  let j = propWords.length - 1;
  for (let i = path.length - 1; i >= 0; i--) {
    if (j >= 0 && path[i] === propWords[j]) j--;
    else context.unshift(path[i]);
  }
  return j < 0 ? context : undefined;
}

/** The spec's CSS value for a gb property bound to `token`. */
export function specValue(db, token, prop) {
  const value = declValue(db, token, WEB_CONTEXT, opacityFor(db, token));
  const suffix = prop.match(/-(axes|tracking)$/)?.[0];
  if (suffix && value?.startsWith('var(--md-sys-typescale-') && !value.endsWith(`${suffix})`)) {
    return value.replace(/\)$/, `${suffix})`);
  }
  return value;
}

/**
 * The opacity token that applies to a color token: `x.color` -> `x.opacity`,
 * or a shared one with a qualifier dropped (`disabled.selected.track.color`
 * -> `disabled.track.opacity`). State-layer colors are excluded: gb applies
 * state-layer opacity in the ripple.
 */
function opacityFor(db, tokenName) {
  if (!tokenName.endsWith('.color') || tokenName.includes('state-layer')) return undefined;
  const parts = tokenName.replace(/\.color$/, '.opacity').split('.');
  if (db.tokens.has(parts.join('.'))) return parts.join('.');
  const head = tokenName.split('.').slice(0, 3).length; // md.comp.<name>
  for (let i = head; i < parts.length - 1; i++) {
    const candidate = [...parts.slice(0, i), ...parts.slice(i + 1)].join('.');
    if (db.tokens.has(candidate)) return candidate;
  }
  return undefined;
}

/** Spellings of a full (pill) corner. */
const FULL_CORNER = /9999px|corner-full|calc\(var\(--[\w-]*height\) \/ 2\)|50cqmin|^50%$/;

/**
 * Values that differ in spelling only: `9999px`/`calc(height / 2)` full
 * corners, `0`/`0px`, `/ 0.38` vs `/ 38%`, spaces inside `var( )`.
 */
export function equivalent(have, want) {
  const canon = (v) =>
    norm(v)
      .replace(/\(\s+/g, '(')
      .replace(/\s+\)/g, ')')
      .replace(/\/ (0?\.\d+|1)\)/g, (_, n) => `/ ${Math.round(Number(n) * 100)}%)`)
      // gb has no `corner-value` properties; the single-radius corner
      // properties have the same value.
      .replace(/--md-sys-shape-corner-value-/g, '--md-sys-shape-corner-');
  if (canon(have) === canon(want)) return true;
  if (FULL_CORNER.test(have) && FULL_CORNER.test(want)) return true;
  // A `+15%` width multiplier spelled as a factor (`1.15`).
  const pct = norm(want).match(/^(\d+(?:\.\d+)?)%$/)?.[1];
  if (Number(pct) > 0 && /^\d+(\.\d+)?$/.test(norm(have)) && Math.abs(Number(have) - (1 + pct / 100)) < 1e-9) {
    return true;
  }
  if (/^0(px)?$/.test(norm(have)) && /^0(px)?$/.test(norm(want))) return true;
  return false;
}
